import { type CallidescopeConfiguration } from "@callidescope/configuration";

/**
 * No output destination is configured on purpose.
 *
 * A generated block in a tracked file has to be regenerated by whoever changes
 * the thing it describes, and this one would change on nearly every pull
 * request. Codometer already documents where that leads — every branch rewrites
 * the same block and conflicts with every other one — which is why it measures
 * on main instead. A call-stack block would inherit that, and something worse:
 * `--check` would fail every pull request whose call graph moved until the
 * author reran `:write`, burying the depth violations it exists to surface.
 *
 * Leaving both destinations unset means nothing can be stale, so the exit code
 * of `nx run codebase:callidescope:check` is purely the violation verdict. The
 * writer and its staleness comparison are implemented and tested; naming a path
 * here is all it takes to turn them on.
 */
const callidescopeConfiguration: CallidescopeConfiguration = {
  excludeFrom: ["configuration/.callidescopeignore"],
  limits: {
    // Thresholds are uncalibrated: they are the issue's example limit and
    // round numbers around it, not measurements of this repository. Run the
    // report, read the distributions, then move these to the knee.
    maximumDepth: 6,
    spreadThreshold: 4,
  },
};

export default callidescopeConfiguration;
